import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# 1) Elementwise addition custom CUDA operator (same pattern as the example)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
)


# ----------------------------------------------------------------------
# 2) Custom CUDA kernel for point‑wise 1D convolution (kernel size=1, stride=1, padding=0)
# ----------------------------------------------------------------------
conv1d_kernel = """
__global__ void conv1d_kernel(const float* in, const float* out,
                               int batch_size, int in_channels,
                               int out_channels, int height, int width) {
    // Each thread computes one output element: (batch, out_channel, y, x)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_channels * height * width) {
        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            // Assume weight[out_channel, in_channel] == 1.0 and bias == 0.0
            int input_offset = ((idx / (out_channels * height * width)) * in_channels) * height * width + ic * height * width;
            sum += in[input_offset];
        }
        out[idx] = sum;
    }
}
"""

conv1d_cpp_source = (
    "torch::Tensor conv1d_cuda(torch::Tensor x, torch::Tensor out);"
)

conv1d_cuda = load_inline(
    name="conv1d_cuda",
    cpp_sources=conv1d_cpp_source,
    cuda_sources=conv1d_kernel,
    functions=["conv1d_cuda"],
    verbose=True,
)


# ----------------------------------------------------------------------
# Optimized model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, bias: bool = False):
        super().__init__()
        self.elementwise_add = elementwise_add   # custom element‑wise addition operator
        self.conv1d_cuda = conv1d_cuda          # custom 1D convolution (pointwise) operator

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x: Input tensor of shape (batch_size, in_channels, height, width)

        Returns:
            Output tensor after applying the point‑wise 2D convolution.
        """
        out = torch.zeros_like(x)   # placeholder; conv1d_cuda will overwrite it
        return self.conv1d_cuda(x, out)


# ----------------------------------------------------------------------
# Example usage (not part of required output)
if __name__ == "__main__":
    model_new = ModelNew(in_channels=64, out_channels=128, bias=False)
    x = torch.rand(16, 64, 1024, 1024)
    y = model_new(x)
    print(y.shape)   # (16, 128, 1024, 1024)
